    seo: { title: "Roof Light Resin Procurement Guide | FRP Roofing Sheet Quote Checklist", keywords: ["Roof Light Resin Supplier", "Roof Light Resin Quote", "FRP Roofing Sheet Resin Procurement", "Roof Light Resin MOQ"], ogTitle: "Roof Light Resin Procurement Guide", ogDescription: "Prepare a documented Roof Light Sheet Grade Resin quotation discussion using the current TDS and factual FRP roofing-sheet requirements." },
    quickFacts: { "Published packaging": "225 kg drum", "Published MOQ": "500 kg", "Product document": "Current Roof Light Resin TDS", "Commercial inputs": "Finished sheet, supplied appearance, quantity and delivery location" },
