    faqs: [{ q: "Is this Epoxy Hardener linked to Clear Casting Resin?", a: "Yes. The published Clear Casting Resin product route identifies a compatible Epoxy Hardener. Confirm the current resin/hardener pairing and documentation before ordering." }, { q: "Is this Epoxy Hardener linked to Epoxy Art Resin?", a: "Yes. The published Epoxy Art Resin route identifies compatible Epoxy Hardener. This does not establish compatibility with every art resin or epoxy product." }],
    sections: [{ heading: "Begin with the resin product route", body: ["Clear Casting Resin and Epoxy Art Resin are separate published epoxy product routes. Clear Casting Resin is positioned for clear, contained casting; Epoxy Art Resin is positioned for art and decorative surface work. Each product route identifies a compatible Epoxy Hardener.", "The hardener relationship should be read alongside the exact resin product and its current data. A buyer should not treat the phrase 'art resin' or 'casting resin' as proof that a hardener from another product system is compatible."] }, { heading: "Use the product role to narrow the discussion", body: ["Where the requirement is a clear contained casting, begin with Clear Casting Resin and its own product information. Where the requirement is an art or decorative surface route, begin with Epoxy Art Resin. This helps identify the resin component before confirming the associated hardener.", "The two routes are not interchangeable product labels, and this guide does not transfer casting-depth, finish, yellowing or other product-specific claims from one route to another."] }, { heading: "What to include in the enquiry", body: ["Provide the exact resin route, intended application, required finish or component, quantity, packaging requirement, delivery location and any requested documentation. Ask for confirmation if the buyer's existing resin product is not the published Samrat route.", "This resource intentionally omits mixing ratios, curing times and use instructions. Use the current product-specific TDS and approved system documentation for those matters."] }],
